import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";

export default function AlertError() {
  return (
    <Alert variant="error">
      <AlertTitle>Tool call failed</AlertTitle>
      <AlertDescription>
        The agent could not run the test suite. The workspace process exited before returning
        results.
      </AlertDescription>
    </Alert>
  );
}

import ExampleAlertError from "../examples/alert-error";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleAlertError />
  </div>
);

export default Example;
